// dag/gunbc/plans/<name>.dag -- minimal plan module (same shape as gunbc.plans.v2_compiler_architecture)
module gunbc.plans.<name>

import std.dissolution { unbound_dissolution }
import gunbc.plan { Plan, PlanRetiresWhen, PlanProjectsCommittedMarkdown }
import std.markdown { MarkdownBlock }
import gunbc.plans.md_helpers { h2, p, li, ul, quote }

fn <name>_body() -> List<MarkdownBlock> {
  [
    quote(blocks: [
      p(text: "**Status:** <design record | program | scope> (<date>, <session>). No implementation lands from this document. DESIGN.md + the carriers remain the authority (DESIGN §6)."),
    ]),
    h2(text: "1. Goal and displaced cost"),
    p(text: "<what pain is removed, denominated as displaced cost>"),
    h2(text: "2. The model (terminal architecture)"),
    p(text: "<the carriers that will survive; cite symbols as `module.name` `decl`, never file:line>"),
    h2(text: "3. Milestones"),
    p(text: "**M1 -- <name>.** **Makes true.** ... **Deletes in the same change.** ... **Production consumer.** ... **Qualification.** <discriminating red + positive control> **Exit.** ..."),
    h2(text: "4. Decisions"),
    ul(items: [
      li(text: "**D1 -- <question>.** <options>. **Ruled <date>:** ... | **Deferred:** trigger is <the capability, not an artifact>."),
    ]),
  ]
}

data <name>_plan: Plan = Plan {
  projection: PlanProjectsCommittedMarkdown,   // or PlanIsAuthorityOnly { ruling: "<commit/ruling that dropped the markdown>" }
  slug: "<name-with-dashes>",
  title: "<title rendered as the H1>",
  body: <name>_body(),
  retirement: PlanRetiresWhen { condition: unbound_dissolution(description: "Delete this document when <the capability that makes it a second copy of the carriers>; <what never dissolves it>.") },
}

// REGISTER (nothing is generated or gated until this lands):
//   dag/gunbc/plan_registry_batch_g.dag:  import gunbc.plans.<name> { <name>_plan }   and append `<name>_plan,` to `batch_g_plans`
// OPTIONAL GOVERNANCE (one row; the banner and children list are derived):
//   dag/gunbc/plan_governance.dag `plan_governance_rows`:
//   PlanGovernance { plan_slug: "<name-with-dashes>", governed_by_slug: "v2-compiler-architecture", role: ImplementationProgram, stage: "<stage>" },
// PROJECT + VERIFY (the generated-artifact gate, tools.generated_artifact_gate):
//   gunbc run --source-root dag --source-root src/v2 --entry dag/gunbc/instruments/generated_artifact_gate.dag --function main_wet     # writes docs/plans/<slug>.md
//   gunbc run --source-root dag --source-root src/v2 --entry dag/gunbc/instruments/generated_artifact_gate.dag --function main         # adjudicates committed bytes
//   (required path: claim_executor --required-ci --required-lane build, GeneratedArtifactPhase)
// LINK FROM A ROADMAP NODE (path string, label "authority"):
//   carriers: carrier(path: "docs/plans/<name-with-dashes>.md"),
